52	- Never use markdown. Plain text only.`;
53	  return _systemPrompt;
54	}
55	
56	type AskAIInput = {
57	  query: string;
58	  history: Array<{ role: "user" | "assistant"; content: string }>;
59	};
60	
61	type ActionItem = { type: "navigate" | "open"; path?: string; url?: string; label?: string };
62	
63	function validateAskAIInput(input: unknown): AskAIInput {
64	  if (!input || typeof input !== "object") {
65	    throw new Error("Expected an AI request payload");
66	  }
67	
68	  const payload = input as Record<string, unknown>;
69	  if (typeof payload.query !== "string" || !payload.query.trim()) {
70	    throw new Error("Expected a non-empty AI query");
71	  }
72	
73	  const history = Array.isArray(payload.history) ? payload.history : [];
74	  return {
75	    query: payload.query.trim().slice(0, 1_000),
76	    history: history
77	      .filter(
78	        (msg): msg is { role: "user" | "assistant"; content: string } =>
79	          !!msg &&
80	          typeof msg === "object" &&
81	          ((msg as { role?: unknown }).role === "user" ||
82	            (msg as { role?: unknown }).role === "assistant") &&
83	          typeof (msg as { content?: unknown }).content === "string",
84	      )
85	      .slice(-6)
86	      .map((msg) => ({ role: msg.role, content: msg.content.slice(0, 1_000) })),
87	  };
88	}
89	
90	function normalizeActions(actions: unknown): ActionItem[] {
91	  if (!Array.isArray(actions)) return [];
92	
93	  return actions.flatMap<ActionItem>((action) => {
94	    if (!action || typeof action !== "object") return [];
95	    const item = action as Record<string, unknown>;
96	    const label = typeof item.label === "string" ? item.label.slice(0, 80) : undefined;
97	
98	    if (item.type === "navigate" && typeof item.path === "string" && item.path.startsWith("/")) {
99	      return [{ type: "navigate", path: item.path, label }];
100	    }
101	
102	    if (item.type === "open" && typeof item.url === "string" && /^https?:\/\//i.test(item.url)) {
103	      return [{ type: "open", url: item.url, label }];
104	    }
105	
106	    return [];
107	  });
108	}
109	
110	export const askAI = createServerFn({ method: "POST" })
111	  .inputValidator(validateAskAIInput)
112	  .handler(async ({ data }) => {
113	    const apiKey = process.env.GROQ_API_KEY;
114	    if (!apiKey) {
115	      return {
116	        response:
117	          "AI not configured. Set GROQ_API_KEY environment variable to enable the AI assistant.",
118	        actions: [] as ActionItem[],
119	      };
120	    }
121	
122	    const systemPrompt = buildSystemPrompt();
123	
124	    const messages: Array<{ role: "system" | "user" | "assistant"; content: string }> = [
125	      { role: "system", content: systemPrompt },
126	      ...data.history.map((msg) => ({
127	        role: (msg.role === "user" ? "user" : "assistant") as "user" | "assistant",
128	        content: msg.content,
129	      })),
130	      { role: "user", content: data.query },
131	    ];
132	
133	    try {
134	      const result = await generateText({
135	        model: groq("llama-3.1-8b-instant"),
136	        messages,
137	        temperature: 0.7,
138	        maxOutputTokens: 300,
139	      });
140	
141	      const text = result.text;
142	
143	      // Parse actions from the response
144	      let actions: ActionItem[] = [];
145	      let cleanText = text;
146	
147	      const actionsMatch = text.match(/\[ACTIONS:\s*(\{.*\})\]/s);
148	      if (actionsMatch) {
149	        try {
150	          const parsed = JSON.parse(actionsMatch[1]);
151	          actions = normalizeActions(parsed.actions);
152	          cleanText = text.replace(/\[ACTIONS:\s*\{.*\}\]/s, "").trim();
153	        } catch {
154	          // ignore parse errors
155	        }
156	      }
157	
158	      return { response: cleanText, actions };
159	    } catch (err) {
160	      console.error("AI SDK error:", err);
161	      return {
162	        response: "AI request failed. Try again.",
163	        actions: [] as ActionItem[],
164	      };
165	    }
166	  });
