1	import { parseMarkdownWithPreview } from "~/utils/markdown";
2	
3	export type BlogPost = {
4	  filename: string;
5	  slug: string;
6	  title: string;
7	  html: string;
8	  preview: string;
9	  description?: string;
10	  date?: string;
11	  tags: string[];
12	};
13	
14	const markdownFiles = import.meta.glob("../blogs/*.md", {
15	  eager: true,
16	  query: "?raw",
17	  import: "default",
18	}) as Record<string, string>;
19	
20	function normalizeString(value: unknown): string | undefined {
21	  return typeof value === "string" && value.trim() ? value.trim() : undefined;
22	}
23	
24	function normalizeTags(value: unknown): string[] {
25	  if (!Array.isArray(value)) return [];
26	  return value
27	    .filter((tag): tag is string => typeof tag === "string")
28	    .map((tag) => tag.trim())
29	    .filter(Boolean);
30	}
31	
32	function parsePost(filePath: string, rawContent: string): BlogPost {
33	  const filename = filePath.split("/").pop() ?? filePath;
34	  const { frontMatter, html, preview } = parseMarkdownWithPreview(rawContent, 400);
35	
36	  const frontMatterTitle = normalizeString(frontMatter.title);
37	  const frontMatterSlug = normalizeString(frontMatter.slug);
38	  const description = normalizeString(frontMatter.description);
39	  const date = normalizeString(frontMatter.date);
40	
41	  const slug = frontMatterSlug || filename.replace(/\.md$/, "");
42	  const title = frontMatterTitle || slug;
43	
44	  return {
45	    filename,
46	    slug,
47	    title,
48	    html,
49	    preview: description ?? preview,
50	    description,
51	    date,
52	    tags: normalizeTags(frontMatter.tags),
53	  };
54	}
55	
56	function comparePosts(a: BlogPost, b: BlogPost): number {
57	  if (a.date && b.date && a.date !== b.date) {
58	    return b.date.localeCompare(a.date);
59	  }
60	  if (a.date && !b.date) return -1;
61	  if (!a.date && b.date) return 1;
62	  return a.title.localeCompare(b.title);
63	}
64	
65	// Lazy-initialize posts to avoid running gray-matter/marked on the client
66	let _posts: BlogPost[] | null = null;
67	function getPosts(): BlogPost[] {
68	  if (!_posts) {
69	    _posts = Object.entries(markdownFiles)
70	      .map(([filePath, rawContent]) => parsePost(filePath, rawContent))
71	      .sort(comparePosts);
72	  }
73	  return _posts;
74	}
75	
76	export const getAllBlogPosts = (): BlogPost[] => [...getPosts()];
77	
78	export const getBlogPostBySlug = (slug: string): BlogPost | undefined =>
79	  getPosts().find((post) => post.slug === slug);
