1	import matter from "gray-matter";
2	import { Marked } from "marked";
3	
4	// Match the options previously passed to Bun.markdown.html:
5	//   autolinks      -> GFM autolink extension (on by default in `marked` with gfm:true)
6	//   hardSoftBreaks -> treat single newlines as <br>
7	const marked = new Marked({ gfm: true, breaks: true });
8	
9	function sanitizeHtml(html: string): string {
10	  return html
11	    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "")
12	    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, "")
13	    .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, "")
14	    .replace(/<object\b[^<]*(?:(?!<\/object>)<[^<]*)*<\/object>/gi, "")
15	    .replace(/<embed\b[^>]*>/gi, "")
16	    .replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
17	    .replace(/\s(href|src)\s*=\s*("|')\s*javascript:[\s\S]*?\2/gi, "")
18	    .replace(/\s(href|src)\s*=\s*javascript:[^\s>]+/gi, "");
19	}
20	
21	export const parseMarkdownWithPreview = (markdownText: string, previewLength = 200) => {
22	  const { data, content } = matter(markdownText);
23	
24	  // Add newlines before headings for better spacing
25	  const formattedContent = content.replace(/^(#{1,6})\s/gm, "\n$1 ").replace(/\n\n\n+/g, "\n\n");
26	
27	  const rawHtml = marked.parse(formattedContent, { async: false }) as string;
28	  const html = sanitizeHtml(rawHtml);
29	
30	  const plainText = html.replace(/<[^>]+>/g, "");
31	  const preview =
32	    plainText.slice(0, previewLength) + (plainText.length > previewLength ? "..." : "");
33	
34	  // Convert any Date objects in frontMatter back to strings
35	  const processedData = { ...data };
36	  if (processedData.date instanceof Date) {
37	    processedData.date = processedData.date.toISOString().split("T")[0];
38	  }
39	
40	  return {
41	    frontMatter: processedData,
42	    html,
43	    preview,
44	  };
45	};
