26	// Scramble text effect - decodes text character by character
27	interface ScrambleTextProps {
28	  text: string;
29	  className?: string;
30	  delay?: number;
31	  speed?: number;
32	}
33	
34	export const ScrambleText = ({
35	  text,
36	  className = "",
37	  delay = 0,
38	  speed = 50,
39	}: ScrambleTextProps) => {
40	  const [displayText, setDisplayText] = useState("");
41	  const [isComplete, setIsComplete] = useState(false);
42	  const chars = "REDACTED!@#$%^&*()";
43	
44	  useEffect(() => {
45	    let timeout: NodeJS.Timeout;
46	    let currentIndex = 0;
47	    let iterations = 0;
48	
49	    const startScramble = () => {
50	      const interval = setInterval(() => {
51	        if (currentIndex >= text.length) {
52	          clearInterval(interval);
53	          setIsComplete(true);
54	          return;
55	        }
56	
57	        setDisplayText((_prev) => {
58	          const revealed = text.slice(0, currentIndex);
59	          const scrambled = text
60	            .slice(currentIndex)
61	            .split("")
62	            .map((char, i) => {
63	              if (char === " ") return " ";
64	              if (i === 0 && iterations > 3) {
65	                currentIndex++;
66	                iterations = 0;
67	                return char;
68	              }
69	              return chars[Math.floor(Math.random() * chars.length)];
70	            })
71	            .join("");
72	
73	          return revealed + scrambled;
74	        });
75	
76	        iterations++;
77	      }, speed);
78	
79	      return () => clearInterval(interval);
80	    };
81	
82	    timeout = setTimeout(startScramble, delay);
83	    return () => clearTimeout(timeout);
84	  }, [text, delay, speed]);
85	
86	  return (
87	    <span className={`terminal-text ${className} ${isComplete ? "" : "opacity-90"}`}>
88	      {displayText ||
89	        text
90	          .split("")
91	          .map(() => "_")
92	          .join("")}
93	    </span>
94	  );
95	};
96	
97	// Typewriter effect
98	interface TypewriterProps {
99	  text: string;
100	  className?: string;
101	  speed?: number;
102	  delay?: number;
103	  cursor?: boolean;
104	}
105	
106	export const Typewriter = ({
107	  text,
108	  className = "",
109	  speed = 80,
110	  delay = 0,
111	  cursor = true,
112	}: TypewriterProps) => {
113	  const [displayText, setDisplayText] = useState("");
114	  const [showCursor, setShowCursor] = useState(true);
115	
116	  useEffect(() => {
117	    let timeout: NodeJS.Timeout;
118	    let index = 0;
119	
120	    timeout = setTimeout(() => {
121	      const interval = setInterval(() => {
122	        if (index >= text.length) {
123	          clearInterval(interval);
124	          return;
125	        }
126	        setDisplayText(text.slice(0, index + 1));
127	        index++;
128	      }, speed);
129	
130	      return () => clearInterval(interval);
131	    }, delay);
132	
133	    return () => clearTimeout(timeout);
134	  }, [text, speed, delay]);
135	
136	  useEffect(() => {
137	    if (!cursor) return;
138	    const interval = setInterval(() => {
139	      setShowCursor((prev) => !prev);
140	    }, 530);
141	    return () => clearInterval(interval);
142	  }, [cursor]);
143	
144	  return (
145	    <span className={`terminal-text ${className}`}>
146	      {displayText}
147	      {cursor && (
148	        <span className={`text-primary ${showCursor ? "opacity-100" : "opacity-0"}`}>|</span>
149	      )}
150	    </span>
151	  );
152	};
