3	export const MatrixRain = () => {
4	  const canvasRef = useRef<HTMLCanvasElement>(null);
5	
6	  useEffect(() => {
7	    const canvas = canvasRef.current;
8	    if (!canvas) return;
9	
10	    const ctx = canvas.getContext("2d");
11	    if (!ctx) return;
12	
13	    const resizeCanvas = () => {
14	      canvas.width = window.innerWidth;
15	      canvas.height = window.innerHeight;
16	    };
17	    resizeCanvas();
18	    window.addEventListener("resize", resizeCanvas);
19	
20	    const chars =
21	      "アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲンREDACTED<>{}[]|/\\";
22	    const charArray = chars.split("");
23	
24	    const fontSize = 14;
25	    const columns = canvas.width / fontSize;
26	
27	    const drops: number[] = [];
28	    for (let i = 0; i < columns; i++) {
29	      drops[i] = Math.random() * -100;
30	    }
31	
32	    const draw = () => {
33	      ctx.fillStyle = "rgba(10, 10, 15, 0.05)";
34	      ctx.fillRect(0, 0, canvas.width, canvas.height);
35	
36	      ctx.fillStyle = "#00f0ff";
37	      ctx.font = `${fontSize}px monospace`;
38	
39	      for (let i = 0; i < drops.length; i++) {
40	        const text = charArray[Math.floor(Math.random() * charArray.length)];
41	
42	        // Gradient effect - brighter at the head
43	        const alpha = Math.random() * 0.5 + 0.1;
44	        ctx.fillStyle = `rgba(0, 240, 255, ${alpha})`;
45	
46	        ctx.fillText(text, i * fontSize, drops[i] * fontSize);
47	
48	        if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
49	          drops[i] = 0;
50	        }
51	        drops[i] += 0.5;
52	      }
53	    };
54	
55	    const interval = setInterval(draw, 50);
56	
57	    return () => {
58	      clearInterval(interval);
59	      window.removeEventListener("resize", resizeCanvas);
60	    };
61	  }, []);
62	
63	  return <canvas ref={canvasRef} className="fixed inset-0 pointer-events-none z-0 opacity-30" />;
64	};
